namespace Plugin\MailMagazine44\Repository;

use Doctrine\Persistence\ManagerRegistry;
use Eccube\Repository\AbstractRepository;
use Plugin\MailMagazine44\Entity\MailMagazineTemplate;

/**
 * MailMagazine.
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 *
 * @extends AbstractRepository<MailMagazineTemplate>
 */
class MailMagazineTemplateRepository extends AbstractRepository
{
    /**
     * MailMagazineTemplateRepository constructor.
     *
     * @param ManagerRegistry $registry
     * @param string $entityClass
     */
    public function __construct(ManagerRegistry $registry, string $entityClass = MailMagazineTemplate::class)
    {
        parent::__construct($registry, $entityClass);
    }

    /**
     * find all.
     *
     * 4.3 以前は HYDRATE_ARRAY で連想配列を返していたが、エンティティ配列を返す。
     *
     * @return list<MailMagazineTemplate>
     */
    public function findAll(): array
    {
        /** @var list<MailMagazineTemplate> $result */
        $result = $this->findBy([], ['id' => 'DESC']);

        return $result;
    }
}
